21	import { LuPlug } from "react-icons/lu";
22	import { RiArchiveStackLine } from "react-icons/ri";
23	import { Link as RouterLink } from "react-router-dom";
24	
25	import type { ExternalViewResponse } from "openapi/requests/types.gen";
26	import { useColorMode } from "src/context/colorMode";
27	import type { NavItemResponse } from "src/utils/types";
28	
29	import { NavButton } from "./NavButton";
30	
31	type Props = { readonly topLevel?: boolean } & NavItemResponse;
32	
33	export const PluginMenuItem = ({
34	  icon,
35	  icon_dark_mode: iconDarkMode,
36	  name,
37	  topLevel = false,
38	  url_route: urlRoute,
39	  ...rest
40	}: Props) => {
41	  // Determine if this is an external view or react app based on the presence of href
42	  const { colorMode } = useColorMode();
43	  const isExternalView = "href" in rest;
44	  const href = isExternalView ? (rest as ExternalViewResponse).href : undefined;
45	
46	  const displayIcon = colorMode === "dark" && typeof iconDarkMode === "string" ? iconDarkMode : icon;
47	  const pluginIcon =
48	    typeof displayIcon === "string" ? (
49	      <Image boxSize={5} src={displayIcon} />
50	    ) : urlRoute === "legacy-fab-views" ? (
51	      <Icon as={RiArchiveStackLine} boxSize={5} />
52	    ) : (
53	      <Icon as={LuPlug} boxSize={5} />
54	    );
55	
56	  const isExternal = urlRoute === undefined || urlRoute === null;
57	
58	  if (topLevel) {
59	    return (
60	      <NavButton
61	        icon={LuPlug}
62	        isExternal={isExternal}
63	        key={name}
64	        pluginIcon={pluginIcon}
65	        title={name}
66	        to={isExternal ? href : `plugin/${urlRoute}`}
67	      />
68	    );
69	  }
70	
71	  return (
72	    <Menu.Item asChild value={name}>
73	      {isExternal ? (
74	        <Link
75	          aria-label={name}
76	          fontSize="sm"
77	          href={href}
78	          outline="none"
79	          rel="noopener noreferrer"
80	          target="_blank"
81	          width="100%"
82	        >
83	          {pluginIcon}
84	          <Box flex="1">{name}</Box>
85	          <Icon as={FiExternalLink} boxSize={4} color="fg.muted" />
86	        </Link>
87	      ) : (
88	        <RouterLink style={{ outline: "none" }} to={`plugin/${urlRoute}`}>
89	          {pluginIcon}
90	          <Box flex="1" ml={2}>
91	            {name}
92	          </Box>
93	        </RouterLink>
94	      )}
95	    </Menu.Item>
96	  );
97	};
