      if (navItem.category !== null && navItem.category !== undefined) {
        categories[navItem.category] = [...(categories[navItem.category] ?? []), navItem];
      } else {
        buttons.push(navItem);
      }
    });
  }

  const hasSubmenu = buttons.length > 0 || Object.keys(categories).length > 0;

